        <Stack spacing={0.5}>
          <Typography variant="h4">{value}</Typography>
          <Typography variant="body2" sx={{ color: 'text.secondary' }}>
            {title}
          </Typography>
        </Stack>

        <Typography variant="caption" sx={{ color: 'text.disabled' }}>
          {trendIsPositive ? 'Increased' : 'Decreased'} from last month
        </Typography>
      </Stack>
