'use client';

import { useState } from 'react';
import { zodResolver } from '@hookform/resolvers/zod';
import { useForm, Controller } from 'react-hook-form';
import { z } from 'zod';

import Box from '@mui/material/Box';
import Card from '@mui/material/Card';
import Chip from '@mui/material/Chip';
import Stack from '@mui/material/Stack';
import Alert from '@mui/material/Alert';
import Switch from '@mui/material/Switch';
import Typography from '@mui/material/Typography';
import MenuItem from '@mui/material/MenuItem';
import TextField from '@mui/material/TextField';
import FormControlLabel from '@mui/material/FormControlLabel';
import Autocomplete from '@mui/material/Autocomplete';
import LoadingButton from '@mui/lab/LoadingButton';
import { DatePicker } from '@mui/x-date-pickers/DatePicker';
import { LocalizationProvider } from '@mui/x-date-pickers/LocalizationProvider';
import { AdapterDayjs } from '@mui/x-date-pickers/AdapterDayjs';

import dayjs, { Dayjs } from 'dayjs';

import { Form, RHFTextField } from 'src/components/hook-form';

// ----------------------------------------------------------------------

const ROLES = [
  { value: 'admin', label: 'Admin' },
  { value: 'editor', label: 'Editor' },
  { value: 'viewer', label: 'Viewer' },
];

const SKILLS = [
  'TypeScript',
  'React',
  'Next.js',
  'MUI',
  'Node.js',
  'Figma',
  'GraphQL',
];

const schema = z.object({
  fullName: z.string().min(2, 'Full name is required'),
  email: z.string().email('Enter a valid email'),
  role: z.string().min(1, 'Role is required'),
  isActive: z.boolean(),
  bio: z.string().max(240, 'Bio must be under 240 characters'),
  skills: z.array(z.string()).min(1, 'Select at least one skill'),
  startDate: z.custom<Dayjs>((val) => dayjs.isDayjs(val), 'Pick a start date'),
});

export type UserProfileValues = z.infer<typeof schema>;

// ----------------------------------------------------------------------

export function UserProfileForm() {
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [showSuccess, setShowSuccess] = useState(false);

  const methods = useForm<UserProfileValues>({
    resolver: zodResolver(schema),
    defaultValues: {
      fullName: '',
      email: '',
      role: '',
      isActive: true,
      bio: '',
      skills: [],
      startDate: dayjs(),
    },
  });

  const { control, handleSubmit } = methods;

  const onSubmit = handleSubmit(async (data) => {
    setIsSubmitting(true);
    setShowSuccess(false);

    // Simulate API call
    await new Promise((resolve) => { setTimeout(resolve, 800); });

    // eslint-disable-next-line no-console
    console.log('Submitted:', data);

    setIsSubmitting(false);
    setShowSuccess(true);
  });

  return (
    <LocalizationProvider dateAdapter={AdapterDayjs}>
      <Form methods={methods} onSubmit={onSubmit}>
        <Card>
          <Stack spacing={3} sx={{ p: 3 }}>
            <Stack spacing={0.5}>
              <Typography variant="h6">User profile</Typography>
              <Typography variant="body2" sx={{ color: 'text.secondary' }}>
                Update account details and preferences
              </Typography>
            </Stack>

            {showSuccess && (
              <Alert severity="success" onClose={() => setShowSuccess(false)}>
                Profile updated successfully.
              </Alert>
            )}

            <Stack direction={{ xs: 'column', sm: 'row' }} spacing={2}>
              <RHFTextField name="fullName" label="Full name" />
              <RHFTextField name="email" label="Email" type="email" />
            </Stack>

            <Stack direction={{ xs: 'column', sm: 'row' }} spacing={2}>
              <Controller
                name="role"
                control={control}
                render={({ field, fieldState: { error } }) => (
                  <TextField
                    {...field}
                    select
                    fullWidth
                    label="Role"
                    error={!!error}
                    helperText={error?.message}
                  >
                    {ROLES.map((role) => (
                      <MenuItem key={role.value} value={role.value}>
                        {role.label}
                      </MenuItem>
                    ))}
                  </TextField>
                )}
              />

              <Controller
                name="startDate"
                control={control}
                render={({ field, fieldState: { error } }) => (
                  <DatePicker
                    {...field}
                    label="Start date"
                    slotProps={{
                      textField: {
                        fullWidth: true,
                        error: !!error,
                        helperText: error?.message,
                      },
                    }}
                  />
                )}
              />
            </Stack>

            <Controller
              name="skills"
              control={control}
              render={({ field, fieldState: { error } }) => (
                <Autocomplete
                  {...field}
                  multiple
                  options={SKILLS}
                  freeSolo
                  value={field.value}
                  onChange={(_, value) => field.onChange(value)}
                  renderTags={(value, getTagProps) =>
                    value.map((option, index) => (
                      <Chip
                        {...getTagProps({ index })}
                        key={option}
                        label={option}
                        size="small"
                        color="info"
                      />
                    ))
                  }
                  renderInput={(params) => (
                    <TextField
                      {...params}
                      label="Skills"
                      placeholder="Pick or type skills"
                      error={!!error}
                      helperText={error?.message}
                    />
                  )}
                />
              )}
            />

            <RHFTextField
              name="bio"
              label="Bio"
              multiline
              rows={4}
              helperText="Short bio under 240 characters"
            />

            <Controller
              name="isActive"
              control={control}
              render={({ field }) => (
                <FormControlLabel
                  control={<Switch {...field} checked={field.value} />}
                  label="Active account"
                />
              )}
            />

            <Stack direction="row" justifyContent="flex-end" spacing={1.5}>
              <LoadingButton
                type="submit"
                variant="contained"
                color="primary"
                loading={isSubmitting}
              >
                Save changes
              </LoadingButton>
            </Stack>
          </Stack>
        </Card>
      </Form>
    </LocalizationProvider>
  );
}

'use client';

import { useState } from 'react';

import Box from '@mui/material/Box';
import Step from '@mui/material/Step';
import Button from '@mui/material/Button';
import Stepper from '@mui/material/Stepper';
import StepLabel from '@mui/material/StepLabel';
import Typography from '@mui/material/Typography';

// ----------------------------------------------------------------------

const STEPS = ['Account', 'Profile', 'Review'];

// ----------------------------------------------------------------------

export function WizardStepper() {
  const [activeStep, setActiveStep] = useState(0);

  const handleNext = () => {
    setActiveStep((prev) => prev + 1);
  };

  const handleBack = () => {
    setActiveStep((prev) => prev - 1);
  };

  const handleReset = () => {
    setActiveStep(0);
  };

  return (
    <Box sx={{ p: 3 }}>
      <Stepper activeStep={activeStep} alternativeLabel>
        {STEPS.map((label) => (
          <Step key={label}>
            <StepLabel>{label}</StepLabel>
          </Step>
        ))}
      </Stepper>

      <Box sx={{ mt: 5, mb: 3 }}>
        {activeStep === STEPS.length ? (
          <>
            <Typography variant="h5" sx={{ mb: 2 }}>
              All steps completed
            </Typography>
            <Typography variant="body2" sx={{ color: 'text.secondary', mb: 3 }}>
              You can now submit the wizard.
            </Typography>
            <Button variant="soft" color="primary" onClick={handleReset}>
              Reset
            </Button>
          </>
        ) : (
          <>
            <Typography variant="h6" sx={{ mb: 1 }}>
              Step {activeStep + 1}: {STEPS[activeStep]}
            </Typography>
            <Typography variant="body2" sx={{ color: 'text.secondary', mb: 3 }}>
              Placeholder content for the {STEPS[activeStep].toLowerCase()} step.
            </Typography>

            <Box sx={{ display: 'flex', justifyContent: 'space-between' }}>
              <Button
                variant="outlined"
                color="inherit"
                disabled={activeStep === 0}
                onClick={handleBack}
              >
                Back
              </Button>

              <Button
                variant="contained"
                color="primary"
                onClick={activeStep === STEPS.length - 1 ? handleReset : handleNext}
              >
                {activeStep === STEPS.length - 1 ? 'Finish' : 'Next'}
              </Button>
            </Box>
          </>
        )}
      </Box>
    </Box>
  );
}

